Il `ContoBancario` del diagramma, in C++: `deposita` accetta solo importi positivi, `preleva` solo importi positivi e non superiori al saldo. Che cosa stampa?

```cpp
#include <iostream>

class ContoBancario {
private:
    float saldo = 0;
public:
    void deposita(float importo) {
        if (importo > 0) saldo += importo;
    }
    void preleva(float importo) {
        if (importo > 0 && importo <= saldo)
            saldo -= importo;
    }
    float ottieniSaldo() const { return saldo; }
};

int main() {
    ContoBancario c;
    c.deposita(100);
    c.preleva(30);
    c.preleva(500);
    c.deposita(-50);
    c.preleva(70);
    c.deposita(25);
    std::cout << c.ottieniSaldo() << "\n";
    return 0;
}
```
